def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.25))

    opp_bids = []
    cindy_bid = None
    urgent_opp_count = 0
    rich_opp_count = 0
    for oid, opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opp_count += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            urgent_opp_count += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            opp_bids.append(float(bid))
            if oid == 'Cindy':
                cindy_bid = float(bid)

    highest_prev = max(opp_bids) if opp_bids else 0.0
    moderate_prev = 0.0
    if opp_bids:
        sorted_bids = sorted(opp_bids)
        idx = int(len(sorted_bids) * 0.5)
        if idx >= len(sorted_bids):
            idx = int(len(sorted_bids) - 1)
        moderate_prev = float(sorted_bids[int(idx)])

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    if danger >= 5:
        base = DAILY_SALARY * (0.95 + 0.20 * scarcity)
    elif danger >= 3:
        base = DAILY_SALARY * (0.72 + 0.18 * scarcity)
    elif danger >= 1:
        base = DAILY_SALARY * (0.52 + 0.16 * scarcity)
    else:
        base = DAILY_SALARY * (0.30 + 0.12 * scarcity)

    if cindy_bid is not None:
        if cindy_bid >= 120:
            if danger <= 1 and supply >= 20:
                base = min(base, DAILY_SALARY * 0.28)
            elif danger >= 3:
                base = max(base, DAILY_SALARY * 0.82)
        elif cindy_bid >= 80:
            base = max(base, min(cindy_bid + 2.0, DAILY_SALARY * 0.92))
        else:
            base = max(base, cindy_bid + 1.5)
    elif highest_prev > 0:
        if highest_prev >= DAILY_SALARY * 0.9:
            if danger <= 1:
                base = min(base, DAILY_SALARY * 0.30)
            else:
                base = max(base, DAILY_SALARY * 0.85)
        else:
            target = max(moderate_prev + 1.5, DAILY_SALARY * (0.45 + 0.10 * scarcity))
            base = max(base, target)

    if urgent_opp_count >= 2 and supply <= 18:
        base = max(base, DAILY_SALARY * 0.88)
    elif urgent_opp_count == 0 and rich_opp_count <= 1 and supply >= 22 and danger == 0:
        base = min(base, DAILY_SALARY * 0.26)

    if day >= 8:
        base *= 1.08
    if day >= 9 and (hp <= 4 or no_water_days >= 1):
        base = max(base, DAILY_SALARY * 0.9)

    reserve_floor = 0.0
    days_left = 10 - day
    if days_left > 1 and danger == 0:
        reserve_floor = DAILY_SALARY * 0.15
    affordable = max(0.0, budget - reserve_floor)
    bid = min(base, affordable if affordable > 0 else budget)

    if danger >= 5:
        bid = min(max(bid, DAILY_SALARY * 0.92), budget)

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only (immediate reaction)
    yesterday_bids = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', None) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate how many water units we can buy if we win allocation for our requirement.
    # Strategy: bid to be competitive, not necessarily maximum.
    # Supply is between 15 and 25, so total water units are about 1-2.
    # We assume each unit corresponds to one WATER_REQ consumption.
    supply_units = int(supply / float(WATER_REQ))
    if supply_units < 1:
        supply_units = 1

    # Pressure signal: if Cindy bid extremely high yesterday, she likely continues.
    cindy_bid = None
    for opp_id, opp in alive_opps:
        if str(opp_id) == 'Cindy':
            prev = opp.get('previous_trace', None) or {}
            if prev.get('bid', None) is not None:
                try:
                    cindy_bid = float(prev['bid'])
                except Exception:
                    cindy_bid = None

    # Base bid level depends on our HP.
    if my_hp <= 2 or my_no_water_days >= 2:
        base = DAILY_SALARY * 0.92
    elif my_hp <= 4:
        base = DAILY_SALARY * 0.70
    else:
        base = DAILY_SALARY * 0.58

    # If Cindy was very aggressive yesterday, raise to avoid being outcompeted.
    if cindy_bid is not None:
        if cindy_bid >= DAILY_SALARY * 1.35:
            base = max(base, DAILY_SALARY * 0.78)
        elif cindy_bid >= DAILY_SALARY * 1.05:
            base = max(base, DAILY_SALARY * 0.65)

    # Also react to the maximum yesterday bid among survivors.
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        # If someone paid near the top, we should ensure we don't lose all units.
        if highest_prev >= DAILY_SALARY * 1.65:
            base = max(base, DAILY_SALARY * 0.80)
        elif highest_prev >= DAILY_SALARY * 1.25:
            base = max(base, DAILY_SALARY * 0.68)

    # Convert base into a budget-feasible bid and add slight day-based variation.
    # Keep within reasonable bounds to avoid running out like the low-survivor agents.
    day_tweak = 1.0 + (int(day) % 3) * 0.03
    bid = base * day_tweak

    # If we can’t afford base, spend what we can but avoid going negative.
    if my_budget <= 0:
        return 0.0

    # Cap bid by budget and also by a soft upper bound linked to supply units.
    # With supply_units=1, being slightly less aggressive can still secure survival.
    soft_cap = DAILY_SALARY * (1.05 if supply_units >= 2 else 0.95)
    bid = min(bid, soft_cap)
    bid = min(bid, my_budget)

    # Ensure non-trivial bid if we’re not in emergency.
    if bid < 1.0 and (my_hp > 2):
        bid = min(my_budget, DAILY_SALARY * 0.45)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 3 or my_status['no_water_days'] > 0:
        bid = DAILY_SALARY * 0.95
    else:
        bid = DAILY_SALARY * 0.5

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if my_status['hp'] <= 3 or my_status['no_water_days'] > 0:
            bid = max(bid, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.8:
            bid = max(bid, DAILY_SALARY * 0.6)
        else:
            bid = max(bid, highest_prev_bid + 2)

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 3:
        bid = max(bid, DAILY_SALARY * 0.75)

    total_water_needed = WATER_REQ * (len(alive_opponents) + 1)
    if day_context['supply'] < total_water_needed:
        bid *= 1.1
    elif day_context['supply'] >= total_water_needed * 1.5:
        bid *= 0.9

    final_bid = min(my_status['budget'], bid)
    final_bid = max(0.0, final_bid)

    return final_bid

